import Foundation
import DHCore
public enum Attribute:String,Codable,CaseIterable,Sendable { case strength,perception,endurance,agility,intellect,charisma,mechanical }
public enum Skill:String,Codable,CaseIterable,Sendable { case mechanics,electrical,driving,firearms,melee,medicine,survival,speech,scavenging }
public enum Injury:String,Codable,Sendable { case bruised,bleeding,fracture,burn,concussion }
public struct CharacterItem:Identifiable,Codable,Sendable,Equatable { public let id:EntityID; public var name:String; public var massKG:Double; public var quantity:Int; public init(id:EntityID=UUID(),name:String,massKG:Double,quantity:Int=1){self.id=id;self.name=name;self.massKG=massKG;self.quantity=quantity} }
public struct CharacterState:Identifiable,Codable,Sendable,Equatable { public let id:EntityID; public var name:String; public var health=100.0; public var hunger=0.0; public var thirst=0.0; public var fatigue=0.0; public var attributes:[Attribute:Int]; public var skills:[Skill:Int]; public var injuries:[Injury]=[]; public var inventory:[CharacterItem]=[]; public var equipped:Set<EntityID>=[]; public init(id:EntityID=UUID(),name:String){self.id=id;self.name=name;attributes=Dictionary(uniqueKeysWithValues:Attribute.allCases.map{($0,5)});skills=Dictionary(uniqueKeysWithValues:Skill.allCases.map{($0,0)})}; public mutating func survivalTick(hours:Double){hunger=min(100,hunger+hours*1.5);thirst=min(100,thirst+hours*3);fatigue=min(100,fatigue+hours*2);if thirst>90{health=max(0,health-hours*2)}}; public var carryMass:Double { inventory.reduce(0){$0+$1.massKG*Double($1.quantity)} } }
